  "a_sentences": [
    {
      "a_text": "P1 Streitig ist vor Bundesgericht die Rechtmässigkeit der Verurteilung der Psychiaterin zur Rückerstattung von Fr. 107'419.05 für das Statistikjahr 2016 wegen Verletzung des Wirtschaftlichkeitsgebots.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Die Vorinstanz stellte gestützt auf die RSS-Daten aller 70 neuchâteloiser Psychiater fest, dass die Indizes der Psychiaterin seit 2012 stets über dem Schwellenwert von 130 lagen (2016: 231).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 Das Bundesgericht hält fest, dass der Nachweis einer Polypragmasie durch die Anwendung spezifischer Methoden zur Analyse von Aktivitätsperioden erfolgt.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Nach der Rechtsprechung liegt Polypragmasie vor, wenn die durchschnittlichen Honorarrechnungen eines Arztes gegenüber Ärzten mit ähnlicher Region und Patientengruppe erheblich höher sind, es sei denn, besondere Umstände rechtfertigen die Kostenunterschiede.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Die Rechtsprechung bestimmt, dass die Toleranzmarge den Index von 130 nicht überschreiten darf und zwischen 120 und 130 liegen muss.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Das Bundesgericht bestätigt, dass der Gesamtkostenindex (direkt und indirekt) der Psychiaterin stets über der Toleranzmarge lag.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Das Bundesgericht verneint eine willkürliche oder rechtsfehlerhafte Beurteilung der Vorinstanz und erkennt keine Überschreitung ihres weiten Ermessens.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Das Bundesgericht berechnet die zu neutralisierende übermässige Kostenquote auf Fr. 51'279.67 und reduziert die Rückerstattungssumme auf Fr. 173'422.58.",
      "b_propositions": ["P8"]
    }
  ]
}
